import unittest

class TestPhase07Challenge(unittest.TestCase):
    def test_graph_nodes_wired(self):
        self.assertTrue('workflow' in globals(), "未找到 StateGraph 工作流定义")
        nodes = set(globals()['workflow'].nodes.keys())
        self.assertIn('agent', nodes, '状态图中应包含 agent 节点')
        self.assertIn('summarizer', nodes, '状态图中应包含 summarizer 摘要节点')

    def test_memory_compiled_app(self):
        self.assertTrue('app' in globals(), "未找到已编译的 LangGraph 应用")
        self.assertTrue(getattr(globals()['app'], 'checkpointer', None), '编译时必须挂载 MemorySaver 检查点，否则多轮记忆无处存放')

    def test_short_conversation_is_not_summarized(self):
        summarize = globals()['summarize_conversation']
        from langchain_core.messages import HumanMessage, AIMessage
        state = {
            'messages': [HumanMessage(content='你好'), AIMessage(content='你好呀')],
            'summary': '',
        }
        result = summarize(state)
        self.assertEqual(result['messages'], [], '对话较短时不应删除任何消息')
        self.assertEqual(result['summary'], '', '对话较短时不应生成摘要')

    def test_summary_trim_targets_earlier_messages(self):
        """参考解策略：保留最后 2 条，删除更早的 8 条

        关键工程细节：LangGraph 的 RemoveMessage 删除语义依赖消息自带的 `id`。
        参考解用 `if m.id` 做防御性判断，手工构造且未赋 id 的消息不会被列入删除
        指令（否则会向 add_messages 传 id=None 而报错）。因此这里显式给消息赋 id，
        模拟真实运行时由 add_messages 自动补齐 id 的场景。
        """
        summarize = globals()['summarize_conversation']
        from langchain_core.messages import HumanMessage, AIMessage, RemoveMessage
        original_build = globals().get('_build_model')
        class FakeResponse:
            content = '用户是 Python 开发者，正在学习 LangGraph。'
        class FakeModel:
            def invoke(self, messages):
                return FakeResponse()
        globals()['_build_model'] = lambda: FakeModel()
        try:
            messages = []
            for i in range(10):
                msg = HumanMessage(content=f'第 {i} 轮消息') if i % 2 == 0 else AIMessage(content=f'第 {i} 轮消息')
                msg.id = f'msg-{i}'
                messages.append(msg)
            result = summarize({'messages': messages, 'summary': ''})
        finally:
            if original_build is None:
                globals().pop('_build_model', None)
            else:
                globals()['_build_model'] = original_build

        self.assertTrue(result['summary'], '超过 6 条消息时必须生成摘要')
        removals = result['messages']
        self.assertTrue(removals, '必须下发删除指令来清理历史消息')
        self.assertTrue(
            all(isinstance(m, RemoveMessage) for m in removals),
            '裁剪历史时必须下发 RemoveMessage，才能触发 add_messages 的删除语义'
        )
        removed_ids = {m.id for m in removals}
        self.assertEqual(
            removed_ids, {f'msg-{i}' for i in range(8)},
            '应删除更早的 8 条消息（保留最后 2 条）'
        )

if __name__ == '__main__':
    unittest.main()

