    def test_reports_four_ragas_metrics(self):
        func = globals()['simulate_ragas_scoring']
        source = inspect.getsource(func)
        for metric in ('Faithfulness', 'Answer Relevance', 'Context Precision', 'Context Recall'):
            self.assertIn(metric, source, f'RAGAS 四件套指标必须全部评测，缺少 {metric}')

