        func = globals()['simulate_ragas_scoring']
        source = inspect.getsource(func)
        self.assertIn('ground_truth', source, '评估必须引入标准答案 (Ground Truth) 才能算召回率')
        self.assertIn('contexts', source, '评估必须引入检索上下文 (Contexts) 才能算精度与忠实度')

    def test_returns_text_and_mutates_case(self):
        func = globals()['simulate_ragas_scoring']
        signature = inspect.signature(func)
        self.assertGreaterEqual(
            len(signature.parameters), 1,
            '参考解当前使用内置案例数据，但为了让评估函数可被自动化测试驱动，请接受一个案例字典参数（参数可带默认值）'
        )

    def test_scores_are_per_metric_judgements(self):
