import unittest
import asyncio
import inspect
import time
from contextlib import contextmanager

class TestPhase11Challenge(unittest.TestCase):
    def test_retry_decorator_exists(self):
        self.assertTrue('retry_llm_call' in globals(), "必须定义 retry_llm_call 装饰器")

    def test_retry_decorator_is_factory(self):
        factory = globals()['retry_llm_call']
        self.assertTrue(callable(factory), "retry_llm_call 必须是可调用的装饰器工厂")

    def test_retries_then_succeeds(self):
        factory = globals()['retry_llm_call']
        calls = {'n': 0}

        @factory(retries=3, delay=0)
        def flaky():
            calls['n'] += 1
            if calls['n'] < 3:
                raise ConnectionError('Connection Timeout')
            return 'ok'

        self.assertEqual(flaky(), 'ok', '第 3 次尝试应当成功返回结果')
        self.assertEqual(calls['n'], 3, '前两次抛错必须被装饰器自动重试')

    def test_raises_after_exhausting_retries(self):
        factory = globals()['retry_llm_call']

        @factory(retries=2, delay=0)
        def always_fail():
            raise RuntimeError('boom')

        with self.assertRaises(Exception):
            always_fail()

    def test_preserves_function_metadata(self):
        factory = globals()['retry_llm_call']

        @factory(retries=1, delay=0)
        def documented():
            """docstring 必须被 functools.wraps 保留"""
            return 1

        self.assertEqual(documented.__name__, 'documented',
                         "装饰器必须使用 functools.wraps，否则 LangChain 无法读取工具名")
        self.assertEqual(documented.__doc__, "docstring 必须被 functools.wraps 保留")

if __name__ == '__main__':
    unittest.main()

