import unittest

class TestPhase14Challenge(unittest.TestCase):
    def test_app_instance_exists(self):
        self.assertTrue('app' in globals(), "必须存在 Celery 实例 app")
        self.assertEqual(globals()['app'].main, 'ai_agent_tasks',
                         "Celery 实例名必须为 ai_agent_tasks")

    def test_serializer_config(self):
        conf = globals()['app'].conf
        self.assertEqual(conf['task_serializer'], 'json', "task_serializer 必须为 json")
        self.assertEqual(conf['result_serializer'], 'json', "result_serializer 必须为 json")
        self.assertEqual(conf['timezone'], 'Asia/Shanghai', "timezone 必须为 Asia/Shanghai")
        self.assertTrue(conf['enable_utc'], "enable_utc 必须开启")

    def test_rate_limit_annotation(self):
        conf = globals()['app'].conf
        annotations = conf.get('task_annotations') or {}
        rate_limit = (annotations.get('tasks.generate_report') or {}).get('rate_limit')
        self.assertEqual(rate_limit, '10/m', "必须为 tasks.generate_report 配置 10/m 限流")

    def test_time_limits(self):
        conf = globals()['app'].conf
        self.assertEqual(conf['task_soft_time_limit'], 300, "软超时必须为 300 秒")
        self.assertEqual(conf['task_time_limit'], 360, "硬超时必须为 360 秒")

    def test_tasks_registered(self):
        # Celery 注册的任务名可能是裸名（tasks.generate_report）或带模块命名空间
        # （如 tasks.tasks.generate_report）。这里只看最后一段，避免评测被模块名差异误伤。
        registered = {name.split('.')[-1] for name in globals()['app'].tasks}
        for name in ('generate_report', 'subagent_research', 'mainagent_summarize', 'sync_vector_db'):
            self.assertIn(name, registered, f"任务 {name} 必须被注册到 Celery 实例")

    def test_generate_report_has_retry_policy(self):
        task = next(t for n, t in globals()['app'].tasks.items()
                    if n.split('.')[-1] == 'generate_report')
        self.assertEqual(task.max_retries, 3, "generate_report 必须开启 3 次自动重试")

    def test_beat_schedule(self):
        beat = globals()['app'].conf.get('beat_schedule') or {}
        self.assertIn('sync-knowledge-base-every-midnight', beat, "必须配置每天同步知识库的定时任务")
        entry = beat['sync-knowledge-base-every-midnight']
        self.assertEqual(entry['task'], 'tasks.sync_vector_db')
        self.assertEqual(float(entry['schedule']), 86400.0, "定时任务周期必须为一天")

if __name__ == '__main__':
    unittest.main()
